<script lang="ts" module>
	const mutex = new Mutex();
</script>

<script lang="ts">
	import { API, Constants, Mutex } from "$lib";
	import { page } from "$app/state";
	import * as ButtonGroup from "$lib/components/ui/button-group";
	import Button from "$lib/components/ui/button/button.svelte";
	import { Spinner } from "$lib/components/ui/spinner";
	import { Session } from "$lib/stores";
	import { cn } from "$lib/Utils";
	import { ThumbsDown, ThumbsUp } from "@lucide/svelte";
	import { StatusCodes } from "http-status-codes";
	import { onDestroy, onMount } from "svelte";
	import { toast } from "svelte-sonner";
	import { createMutationOwner } from "$platform/authenticated-mutation";
	import { nativeAuthority, captureNativeAuthority, sameNativeReadAuthority } from "$platform/mutation-authority";
	import { useComments } from "./context.svelte";

	const comments = useComments();
	const mutationOwner = createMutationOwner(() => JSON.stringify([comments.thread.id, page.url.href]));
	$effect(() => { JSON.stringify([comments.thread.id, page.url.href]); mutationOwner.invalidate(); });

  let voteReadDisposed = false, voteReadGeneration = 0, voteReadController: AbortController | undefined;
  onDestroy(() => { voteReadDisposed = true; voteReadGeneration++; voteReadController?.abort(); });
  $effect(() => {
    const threadId = comments.thread.id, actor = $nativeAuthority.actor, epoch = $nativeAuthority.epoch;
    const generation = ++voteReadGeneration, authority = captureNativeAuthority();
    voteReadController?.abort(); const controller = new AbortController(); voteReadController = controller;
    comments.voteState = undefined;
    if (!actor) return () => controller.abort();
    void API.Thread.GetThreadVote(threadId, controller.signal).then(res => {
      if (voteReadDisposed || controller.signal.aborted || generation !== voteReadGeneration || threadId !== comments.thread.id || !sameNativeReadAuthority(authority)) return;
      if (res?.status === StatusCodes.OK && res.body && [-1, 0, 1].includes(res.body.vote)) comments.voteState = res.body.vote;
      else if (res?.status === StatusCodes.NO_CONTENT) comments.voteState = 0;
    }).catch(() => { /* Unknown personal state must be freshly read before a write. */ });
    return () => controller.abort();
  });
  let mutexVoteState = $state<-1 | 1>();
  const mutateThreadVote = (value: -1 | 1) => {
    if (mutex.isLocked()) return;
    if (!$Session) { toast.error("Please sign in to perform this action"); return; }
    if (!comments.stats) return;
    const intent = mutationOwner.capture(), threadId = comments.thread.id;
    return mutex.exec(async () => {
      mutexVoteState = value;
      try {
        intent.assert();
        // A click never interprets missing/stale personal state as an absent vote.
        const personal = await API.Thread.GetThreadVote(threadId, intent.signal); intent.assert();
        const previous = personal?.status === StatusCodes.NO_CONTENT ? 0 : personal?.status === StatusCodes.OK ? personal.body?.vote : undefined;
        if (previous === undefined || ![-1, 0, 1].includes(previous)) throw new Constants.Error.Error("Vote status unavailable", "The current vote could not be confirmed. No change was submitted.");
        const remove = previous === value;
        const res = await (remove ? API.Thread.UnvoteThread(threadId, intent) : API.Thread.VoteThread(threadId, value, intent)); intent.assert();
        if (res?.status === StatusCodes.NO_CONTENT) {
          voteReadGeneration++; voteReadController?.abort();
          comments.voteState = remove ? 0 : value;
          const current = await API.Thread.Get(threadId); intent.assert();
          if (current?.status !== StatusCodes.OK || !current.body?.relationships.stats) throw new Constants.Error.Error("Vote acknowledged", "Your vote change succeeded, but current counts could not be loaded. Reload this discussion; the change was not replayed.");
          comments.stats = { ...current.body.relationships.stats };
        } else if (res?.status === StatusCodes.FORBIDDEN) throw Constants.Error.Forbidden;
        else if (res?.status === StatusCodes.CONFLICT) throw Constants.Error.UpdateConflict;
        else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) throw Constants.Error.TooManyRequests;
        else throw Constants.Error.Unknown;
      } catch (cause) { if (!intent.alive()) return; const error = cause instanceof Constants.Error.Error ? cause : Constants.Error.Unknown; toast.error(error.title, { description: error.body }); }
      finally { mutexVoteState = undefined; intent.release(); }
    });
  };
  const onVote = (value: -1 | 1) => mutateThreadVote(value);
  const onDeleteVote = (value: -1 | 1) => mutateThreadVote(value);
</script>

<ButtonGroup.Root>
	<Button
		aria-label="Upvote chapter or discussion"
		class={cn("text-muted-foreground border-0", {
			"!border-accent text-accent-foreground border-b-2": comments.voteState === 1
		})}
		variant="outline"
		onclick={e => {
			e.stopPropagation();
			e.stopImmediatePropagation();
			onVote(1);
		}}
	>
		{#if $mutex && mutexVoteState === 1}
			<Spinner />
		{:else}
			<ThumbsUp />
		{/if}
		{#if comments.stats?.up}
			{comments.stats?.up.toLocaleString()}
		{/if}
	</Button>
	<ButtonGroup.Separator />
	<Button
		aria-label="Downvote chapter or discussion"
		class={cn("text-muted-foreground border-0", {
			"!border-accent text-accent-foreground border-b-2": comments.voteState === -1
		})}
		variant="outline"
		size="icon"
		onclick={e => {
			e.stopPropagation();
			e.stopImmediatePropagation();
			onVote(-1);
		}}
	>
		{#if $mutex && mutexVoteState === -1}
			<Spinner />
		{:else}
			<ThumbsDown />
		{/if}
	</Button>
</ButtonGroup.Root>
